import ast, hashlib, pathlib
root = pathlib.Path(__file__).resolve().parent
original = (root / "archive-596-v6.py").read_bytes()
assert hashlib.sha256(original).hexdigest() == "ec441791152f95705e336739314e8d6077a8562b5bca9feb42a798b8d5d84391"
text = original.decode("utf-8")
old = "roles = {item[\"role\"] for item in recipe.get(\"actualReceipts\", [])}\nfor directory in recipe.get(\"evidenceDirs\", []):\n    assert directory.get(\"completedOwnerReceiptRole\") in roles, \"Directory needs selected actual closed owner\"\n"
new = "roles = {item[\"role\"] for item in recipe.get(\"actualReceipts\", [])}\nreceipts_by_role = {item[\"role\"]: item for item in recipe.get(\"actualReceipts\", [])}\nlegacy_directory_owners = {\n    \"private/raw/before-f9-v3\": (\"root/browser-private-before-f9-v3\", \"private/preparation-v3/run-private-preferences-browser-v3.mjs\", \"absolute-out-equals\"),\n    \"private/raw/after-built-v3\": (\"root/browser-private-after-built-v3\", \"private/preparation-v3/run-private-preferences-browser-v3.mjs\", \"absolute-out-equals\"),\n    \"private/raw/before-f9-v4\": (\"root/browser-private-before-f9-v4\", \"private/preparation-v4/run-private-preferences-browser-v4.mjs\", \"absolute-out-equals\"),\n    \"private/raw/after-built-v4\": (\"root/browser-private-after-built-v4\", \"private/preparation-v4/run-private-preferences-browser-v4.mjs\", \"absolute-out-equals\"),\n    \"route/v1-raw\": (\"root/browser-route-v1\", \"route/v1-runner\", \"original-runner-relative-out\"),\n}\ndirectory_owner_bindings = []\nfor directory in recipe.get(\"evidenceDirs\", []):\n    original_role = directory.get(\"completedOwnerReceiptRole\")\n    owner_role = original_role\n    runner_proof = None\n    if original_role is None:\n        assert directory[\"alias\"] in legacy_directory_owners, \"Only five exact original missing-owner directory schemas may use explicit bindings\"\n        owner_role, runner_alias, output_kind = legacy_directory_owners[directory[\"alias\"]]\n        owner_item = receipts_by_role[owner_role]\n        assert pathlib.Path(owner_item[\"path\"]).name == owner_role.split(\"/\")[-1] + \".result.json\"\n        owner_actual, owner_bytes = physical(owner_item[\"path\"])\n        owner = json.loads(owner_bytes)\n        assert owner.get(\"closedAt\") and type(owner.get(\"actualExitCode\")) is int and owner.get(\"signal\") is None and not owner.get(\"spawnError\")\n        command_args = owner[\"args\"]\n        runner_frozen = frozen_by_alias[runner_alias]\n        assert pathlib.Path(command_args[0]).resolve() == pathlib.Path(runner_frozen[\"path\"]).resolve(), \"Exact frozen original runner required\"\n        runner_proof, runner_bytes = physical(runner_frozen[\"path\"])\n        assert runner_proof[\"bytes\"] == runner_frozen[\"bytes\"] and runner_proof[\"sha256\"] == runner_frozen[\"sha256\"] and str(runner_proof[\"mtimeNs\"]) == str(runner_frozen[\"mtimeNs\"])\n        if output_kind == \"absolute-out-equals\":\n            output_args = [arg[len(\"--out=\"):] for arg in command_args if arg.startswith(\"--out=\")]\n            assert len(output_args) == 1 and pathlib.Path(output_args[0]).is_absolute()\n            expected_directory = pathlib.Path(output_args[0]).resolve()\n        else:\n            assert command_args.count(\"--out\") == 1 and command_args[command_args.index(\"--out\") + 1] == \"results-v1\"\n            runner_text = runner_bytes.decode(\"utf-8\")\n            assert \"const root = dirname(fileURLToPath(import.meta.url))\" in runner_text and \"const out = resolve(root, label)\" in runner_text\n            expected_directory = (pathlib.Path(command_args[0]).parent / \"results-v1\").resolve()\n        assert expected_directory == pathlib.Path(directory[\"path\"]).resolve(), \"Exact original closed owner's output directory required\"\n        binding_source = \"explicit-frozen-alias; original directory recipe has no owner field; original receipt args and frozen runner bind output\"\n    else:\n        assert original_role in roles, \"Directory needs selected actual closed owner\"\n        owner_actual, owner_bytes = physical(receipts_by_role[owner_role][\"path\"])\n        binding_source = \"original-directory-declared-owner-role\"\n    assert owner_role in roles, \"Directory needs selected actual closed owner\"\n    directory_owner_bindings.append({\"alias\": directory[\"alias\"], \"directory\": directory[\"path\"], \"originalOwnerRoleDeclared\": original_role is not None, \"completedOwnerReceiptRole\": owner_role, \"bindingSource\": binding_source, \"ownerReceipt\": owner_actual, \"runner\": runner_proof})\n"
assert text.count(old) == 1
text = text.replace(old,new)
old_index = '"receiptStreamBindings": receipt_stream_bindings, "files": files'
new_index = '"receiptStreamBindings": receipt_stream_bindings, "directoryOwnerBindings": directory_owner_bindings, "files": files'
assert text.count(old_index) == 1
text = text.replace(old_index,new_index)
ast.parse(text)
target = root / "archive-596-v7.py"
with target.open("xb") as handle: handle.write(text.encode("utf-8"))
print(str(target),target.stat().st_size,hashlib.sha256(target.read_bytes()).hexdigest())
